<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {defaultProject,validateProject,parseProject,projectPosition} from '../../room/projects.js';
import {useLocalDraft} from '../../composables/useLocalDraft.js';
import {readWorks,readDrafts,workTypes} from '../../room/workshelf.js';
import {downloadJson} from '../../room/storage.js';
import {downloadStage} from '../../room/exportImage.js';
import {lightFrame} from '../../room/creativeTools.js';
import {patternSounds} from '../../room/pattern.js';
import {useInteractionAudio} from '../../composables/useInteractionAudio.js';
import {createGuitarEffectsEngine} from '../../audio/guitarEffectsEngine.js';
import {assetUrl} from '../../data/site.js';
import {cast} from '../../data/playroom.js';
import {recordActivity} from '../../room/activityLog.js';
import {rasterData} from '../../services/safeMedia.js';
const {state,saved,persist}=useLocalDraft('hitori-room:project:v1',defaultProject,validateProject,{validateOnSave:true});
const works=ref(readWorks()),choices=ref({studio:'',lights:'',effects:'',backdrop:'',poster:''}),message=ref('先挑自己的编曲与灯光，再为舞台放一幅画。'),playing=ref(false),starting=ref(false),position=ref({step:0,cycle:1,fraction:0}),stage=ref(null),file=ref(null);
const audio=useInteractionAudio('project-studio');
const engine=createGuitarEffectsEngine({createContext:()=>{const A=window.AudioContext||window.webkitAudioContext;return new A();},isHidden:()=>document.hidden});
let frame,origin,previous=-1,generation=0,alive=true;
const lights=computed(()=>lightFrame(state.value.lights,position.value.step,position.value.fraction));
const artwork=computed(()=>works.value.filter(w=>w.preview));
const selection=(kind)=>works.value.filter(w=>w.kind===kind);
function refresh(){works.value=readWorks();}
function usePart(kind){try{const value=choices.value[kind];const source=value==='draft'?readDrafts().find(d=>d.kind===kind):works.value.find(w=>w.id===value);if(!source)throw new Error('先保存一份对应作品，再回来选择。');const key={studio:'pattern',lights:'lights',effects:'tone'}[kind];state.value[key]=structuredClone(source.snapshot);if(kind==='effects')state.value.useTone=true;message.value=`已装入${workTypes[kind].label}，项目会保留独立副本。`;}catch(e){message.value=e.message;}}
function useImage(slot){const selected=works.value.find(w=>w.id===choices.value[slot]);state.value[slot]=selected?.preview||'';}
function useStageBackdrop(){try{const value=localStorage.getItem('hitori-room:stage-background:v1');if(!rasterData(value,1500000))throw new Error();state.value.backdrop=value;message.value='已收好涂鸦墙的舞台背景。';}catch{message.value='先在涂鸦墙保存一张舞台背景。';}}
function stop(){generation++;playing.value=false;starting.value=false;cancelAnimationFrame(frame);audio.stop();engine.stop();}
function tick(now){if(!playing.value)return;const elapsed=now-origin,pos=projectPosition(elapsed,state.value);if(pos.done){stop();message.value='这场演出完成了，可以保存项目，或再演一遍。';recordActivity('project',state.value.name,JSON.stringify(state.value));return;}position.value=pos;const absolute=Math.floor(elapsed/(60000/state.value.pattern.bpm/4));if(absolute!==previous){previous=absolute;for(const track of patternSounds(state.value.pattern,pos.step)){if(state.value.useTone&&track.sound==='guitar')engine.play(track.frequency);else audio.play(track.sound,track.frequency);}}frame=requestAnimationFrame(tick);}
async function play(){stop();const token=++generation;starting.value=true;try{validateProject(state.value);engine.setPreset(state.value.tone);engine.setVolume(audio.volume.value);const [enabled,ready]=await Promise.all([audio.setEnabled(true),state.value.useTone?engine.unlock():Promise.resolve(true)]);if(!alive||token!==generation||document.hidden)return;if(!enabled||!ready)throw new Error('音效暂未准备好，请再点一次播放。');starting.value=false;playing.value=true;origin=performance.now();previous=-1;message.value='灯光与编曲正在按同一个节拍演出。';frame=requestAnimationFrame(tick);}catch(e){stop();message.value=e.message;}}
async function importFile(e){const f=e.target.files?.[0];if(!f)return;try{if(f.size>2200000)throw new Error('项目文件不能超过2.2MB。');const next=parseProject(await f.text());if(!alive)return;stop();state.value=next;message.value='已载入完整项目，包括编曲、灯光、音色与画面。';}catch(error){message.value=error.message;}finally{e.target.value='';}}
function exportProject(){try{persist();downloadJson(validateProject(state.value),'hitori-live-project.json');message.value='整场演出已打包，导入项目即可继续播放与编辑。';}catch(e){message.value=e.message;}}
async function photo(){try{await downloadStage(stage.value,'hitori-live-stage.png');message.value='演出画面已保存。';}catch(e){message.value=e.message;}}
function hidden(){if(document.hidden)stop();}
watch(()=>state.value.pattern.bpm,stop);watch(audio.enabled,v=>{if(!v)stop();});watch(audio.volume,v=>engine.setVolume(v));
window.addEventListener('hitori:works-changed',refresh);document.addEventListener('visibilitychange',hidden);
onBeforeUnmount(()=>{alive=false;stop();engine.dispose();window.removeEventListener('hitori:works-changed',refresh);document.removeEventListener('visibilitychange',hidden);});
</script>
<template><section class="room-panel" aria-labelledby="project-title"><p class="play-eyebrow">从第一拍，到最后一束光</p><h2 id="project-title">把今晚，排成一场完整演出。</h2><p class="room-intro">编曲与灯光共享节拍。挑选的作品会作为副本保存在项目里，之后整理或移走原作品也不会让演出缺页。</p><div class="room-fields"><label class="room-field">演出名称<input v-model="state.name" maxlength="60"></label><label class="room-field">速度 BPM<input v-model.number="state.pattern.bpm" type="number" min="60" max="180"></label><label class="room-field">循环次数<select v-model.number="state.cycles"><option v-for="n in [1,2,4,8,16]" :key="n" :value="n">{{n}}轮</option></select></label></div>
 <svg ref="stage" viewBox="0 0 900 520" class="project-stage" role="img" aria-label="完整演出舞台"><defs><linearGradient v-for="(light,i) in lights" :id="`project-light-${i}`" :key="i" x2="0" y2="1"><stop :stop-color="light.color" stop-opacity=".65"/><stop offset="1" :stop-color="light.color" stop-opacity=".06"/></linearGradient></defs><rect width="900" height="520" fill="#292334"/><image v-if="state.backdrop" :href="state.backdrop" width="900" height="450" preserveAspectRatio="xMidYMid slice" opacity=".65"/><path d="M0 55Q150 150 300 55Q450 150 600 55Q750 150 900 55V0H0Z" fill="#59415c"/><rect y="430" width="900" height="90" fill="#654c64"/><g v-for="(l,i) in lights" :key="i" :opacity="l.intensity"><path :d="`M${150+i*300} 35L${l.x-160} 445L${l.x+160} 445Z`" :fill="`url(#project-light-${i})`"/><ellipse :cx="l.x" cy="435" rx="155" ry="20" :fill="l.color" opacity=".5"/></g><image v-if="state.poster" :href="state.poster" x="28" y="170" width="130" height="175" preserveAspectRatio="xMidYMid meet"/><image v-for="(m,i) in cast" :key="m.id" :href="assetUrl(m.image)" :x="190+i*155" y="260" width="110" height="175"/><text x="450" y="485" text-anchor="middle" fill="#f4dfe7" font-size="24">{{state.name}}</text></svg>
 <div class="timeline-steps" aria-label="当前演出步数"><span v-for="n in 16" :key="n" :class="{on:position.step===n-1}"></span></div><p class="room-hint">第{{position.cycle}}轮 / {{state.cycles}}轮 · 第{{position.step+1}}步</p><div class="room-actions"><button v-if="!playing" id="project-play" class="primary" type="button" :disabled="starting" @click="play">{{starting?'准备中…':'开始完整演出'}}</button><button v-else type="button" @click="stop">停止演出</button><button type="button" @click="photo">保存演出画面 PNG</button><button type="button" @click="exportProject">导出完整项目 JSON</button><button type="button" @click="file.click()">导入完整项目</button><input ref="file" hidden type="file" accept=".json,application/json" aria-label="选择演出项目" @change="importFile"></div>
 <div class="project-parts"><div v-for="(label,kind) in {studio:'编曲',lights:'灯光',effects:'吉他音色'}" :key="kind"><label class="room-field">从作品架装入{{label}}<select v-model="choices[kind]"><option value="">选择一个版本</option><option value="draft">当前本机草稿</option><option v-for="w in selection(kind)" :key="w.id" :value="w.id">{{w.title}}</option></select></label><div class="room-actions"><button type="button" @click="usePart(kind)">装入{{label}}</button><RouterLink :to="`/room/${kind}`">去编辑 ↗</RouterLink></div></div><div v-for="(label,slot) in {backdrop:'舞台背景',poster:'海报或合影'}" :key="slot"><label class="room-field">{{label}}<select v-model="choices[slot]" @change="useImage(slot)"><option value="">不放画面</option><option v-for="w in artwork" :key="w.id" :value="w.id">{{w.title}}</option></select></label></div></div><div class="room-actions"><button type="button" @click="useStageBackdrop">装入涂鸦墙舞台背景</button><label class="room-check"><input v-model="state.useTone" type="checkbox">使用项目内的吉他音色</label></div><p role="status" class="room-status">{{message}}</p><p class="room-hint">{{saved?'项目草稿已保存在本机。':'本机暂不能保存，请导出项目备份。'}} 上方“存入作品架”可以保留多个完整演出版本。离开页面或切到后台会停止播放。</p></section></template>
